    'export reducer from "./reducer";\n'
  );
});

test("prints export namespace specifiers without braces", () => {
  expect(format("export * as ns from './reducer'")).toBe(
    'export * as ns from "./reducer";\n'
  );
});

test("prints mixed export extension and named specifiers", () => {
  expect(format("export reducer, { foo as bar } from './reducer'")).toBe(
    'export reducer, { foo as bar } from "./reducer";\n'
  );
});

function printExportDeclaration(path, options, print) {
  var decl = path.getValue();
  var parts = [ "export " ];

  namedTypes.Declaration.assert(decl);

  if (decl["default"] || decl.type === "ExportDefaultDeclaration") {
    parts.push("default ");
  }

  if (decl.declaration) {
    parts.push(path.call(print, "declaration"));

    if (
      decl.type === "ExportDefaultDeclaration" &&
        (decl.declaration.type !== "ClassDeclaration" &&
          decl.declaration.type !== "FunctionDeclaration" &&
          decl.declaration.type !== "FunctionExpression")
    ) {
      parts.push(";");
    }
  } else {
    if (decl.specifiers && decl.specifiers.length > 0) {
      if (
        decl.specifiers.length === 1 &&
          decl.specifiers[0].type === "ExportBatchSpecifier"
      ) {
        parts.push("*");
      } else {
        var standalones = [];
        var grouped = [];

        path.each(function(specifierPath) {
          var value = specifierPath.getValue();
          if (
            namedTypes.ExportDefaultSpecifier.check(value) ||
              namedTypes.ExportNamespaceSpecifier.check(value)
          ) {
            standalones.push(print(specifierPath));
          } else {
            grouped.push(print(specifierPath));
          }
        }, "specifiers");

        parts.push(decl.exportKind === "type" ? "type " : "");

        if (standalones.length > 0) {
          parts.push(join(", ", standalones));
        }

        if (grouped.length > 0) {
          if (standalones.length > 0) {
            parts.push(", ");
          }

          parts.push(
            multilineGroup(
              concat([
                "{",
                indent(
                  options.tabWidth,
                  concat([
                    options.bracketSpacing ? line : softline,
                    join(concat([ ",", line ]), grouped)
                  ])
                ),
                ifBreak(options.trailingComma ? "," : ""),
                options.bracketSpacing ? line : softline,
                "}"
              ])
            )
          );
        }
      }
    } else {
      parts.push("{}");
    }

    if (decl.source) {
      parts.push(" from ", path.call(print, "source"));
    }

    parts.push(";");
  }

