const assert = require('assert');
const prettier = require('./');

const cases = [
  [\"export reducer from './reducer'\", 'export reducer from \"./reducer\";\\n'],
  [\"export * as ns from './reducer'\", 'export * as ns from \"./reducer\";\\n'],
  [\"export reducer, { foo as bar } from './reducer'\", 'export reducer, { foo as bar } from \"./reducer\";\\n'],
  [\"export { foo as bar } from './reducer'\", 'export { foo as bar } from \"./reducer\";\\n']
];

for (const [input, expected] of cases) {
  const actual = prettier.format(input, { parser: 'babylon' });
  assert.strictEqual(actual, expected, "'`Unexpected output for ${input}'"\\nActual: "'${actual}'"\\nExpected: "'${expected}`);
}

console.log(`verified ${cases.length} formatter cases`);
